#!/usr/bin/env bash
set -euo pipefail

# These tests exercise functional and crash-recovery boundaries without a load generator.
lightweight_filter='test(=tests::lightweight::postgres_migration_engine::optional_postgres_migration_engine_uses_real_source_and_target_fixture) | test(=tests::lightweight::postgres_migration_engine::optional_postgres_migration_target_uses_real_pool_transactions) | test(=tests::lightweight::postgres_migration_engine::optional_postgres_migration_engine_recovers_after_process_sigkill) | test(=tests::lightweight::postgres_migration_engine::migration_source_ack_uncertainty_is_idempotent_after_commit) | test(=tests::lightweight::postgres_migration_engine::migration_engine_restarts_after_apply_ack_failure_without_loss_or_resurrection) | test(=tests::lightweight::postgres_migration_engine::migration_engine_copies_catches_up_verifies_and_publishes_authority) | test(=tests::lightweight::postgres_migration_engine::switch_catches_up_source_writes_during_large_pre_fence_verification) | test(=tests::lightweight::postgres_migration_engine::migration_switch_serializes_concurrent_authority_attempts) | test(=tests::lightweight::postgres_migration_engine::migration_verification_stops_when_shutdown_is_cancelled) | test(=tests::lightweight::postgres_migration_engine::migration_switch_keeps_source_fenced_after_indeterminate_publication) | test(=tests::lightweight::postgres_migration_engine::migration_switch_retries_after_recovery_with_next_authority_generation) | test(=tests::lightweight::postgres_migration_engine::migration_switch_abort_does_not_leave_source_fenced) | test(=tests::lightweight::postgres_migration_engine::migration_switch_retries_after_tail_failure_without_generation_drift) | test(=tests::lightweight::postgres_migration_engine::migration_switch_fails_closed_for_pre_fenced_source_authority) | test(=tests::lightweight::postgres_migration_engine::migration_switch_fails_closed_when_source_fence_rollback_fails) | test(=tests::lightweight::storage_migration_status::postgres_cutover_publishes_postgres_authority_and_completed_module) | test(=tests::lightweight::postgres_tests::native_sqlite_capture_triggers_capture_and_fence_legacy_writes) | test(=tests::lightweight::postgres_tests::archive_native_insert_path_uses_owner_target_columns_when_postgres_is_available) | test(=tests::lightweight::postgres_tests::optional_postgres_storage_transaction_smoke_test)'
archive_filter='test(=tests::archive_file_io::archive_postgres_adapter::postgres_archive_ownership_is_cross_batch_and_release_retry_monotonic) | test(=tests::archive_file_io::archive_postgres_adapter::postgres_archive_release_and_prune_wait_for_live_raw_link_transactions) | test(=tests::archive_file_io::archive_postgres_adapter::postgres_archive_prune_ledger_upgrade_backfills_only_recoverable_paths) | test(=tests::archive_file_io::terminal_journal_recovery::valid_attempt_ack_does_not_create_a_false_interruption_after_isolation) | test(=tests::archive_file_io::shutdown_terminal_recovery::shutdown_recovery_ack_failure_keeps_obligation_without_poisoning_main_journal)'
bash .github/scripts/run-backend-tests.sh --profile lightweight --test-filter "$lightweight_filter"
BACKEND_TEST_ARCHIVE_FILE_IO_THREADS=1 bash .github/scripts/run-backend-tests.sh --profile archive-file-io --test-filter "$archive_filter"
